import{z as d,x as A,o as t,c as p,q as r,j as l,D as i,d as s,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"分布式缓存失效","description":"","frontmatter":{"title":"分布式缓存失效","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/distributed-cache-invalidation.md","filePath":"cs/distributed-cache-invalidation.md","lastUpdated":1791063341000}'),B={name:"cs/distributed-cache-invalidation.md"};function T(m,a,c,h,u,D){const E=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="分布式缓存失效" tabindex="-1">分布式缓存失效 <a class="header-anchor" href="#分布式缓存失效" aria-label="Permalink to &quot;分布式缓存失效&quot;">​</a></h1><div class="epigraph"><p>写库后通知缓存删键。通知丢失或乱序，缓存就永远脏。失效是尽力而为的提示，TTL 与版本才是保险。</p><footer>—— 据 Gray and Cheriton 租约缓存；Nishtala et al., Scaling Memcache at Facebook, NSDI 2013 整理</footer></div><p>上一课<a href="/cs/pub-sub">发布订阅</a>常被拿来发「这个键脏了」。缺口是<strong>失效消息不是线性一致读路径</strong>：丢一条就脏到 TTL。本课钉失效与租约/TTL 的组合，不重写 Merkle 反熵。后课雪崩是失效或过期对齐时的读打穿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>旁路缓存：读 miss 打库再填；写库再删缓存（或先删后写，各有窗口）。分布式后有多缓存节点、多写者。失效总线丢消息 ⇒ 永久脏直到 TTL。乱序：先写新值的失效晚到，把新填的缓存又删，或旧失效打掉新值后旧填充回来。</p><p>缺口：把 memcache 当线性一致层。Facebook 的 NSDI 论文描述租约防惊群、以及失效与填充的竞态，不是「缓存强一致」。</p><p><span class="marginnote">Gray–Cheriton 租约让服务器在写前等租约到期，缓存侧有期限。纯 pub-sub 失效没有这层算术。</span></p><p><span class="marginnote">术语翻译：旁路缓存（cache-aside）就是「缓存是应用自己的笔记本，存储系统根本不知道它存在」——读时先翻笔记，没有再去查库并抄一份；写时先改库，再把自己笔记本上那页撕掉（删键）。与「读穿透/写穿透」相反：后者由缓存组件替你跑腿，应用只跟缓存说话。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>组合：短 TTL（最终正确）+ 尽力失效（尽快正确）+ 版本/cas（填充时核对）。写路径：更新存储的版本，填充带版本，失效带版本，旧填充不得覆盖新。租约：fill 时持短租约，防同一 miss 打穿。</p>',10)),(t(),l(o,null,{default:i(()=>[n(E,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E5%AD%98%E5%82%A8%22%5D%20--%3E%20INV%5B%22%E5%8F%91%E5%A4%B1%E6%95%88%22%5D%0A%20%20INV%20--%3E%20DEL%5B%22%E7%BC%93%E5%AD%98%E5%88%A0%E9%94%AE%22%5D%0A%20%20INV%20-.-%3E%20LOSS%5B%22%E4%B8%A2%E5%A4%B1%20%E2%87%92%20%E9%9D%A0%20TTL%22%5D%0A%20%20MISS%5B%22%E8%AF%BB%20miss%22%5D%20--%3E%20FILL%5B%22%E5%A1%AB%E5%85%85%22%5D%0A%20%20FILL%20--%3E%20VER%5B%22%E7%89%88%E6%9C%AC%20%2F%20cas%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"不要用跨机墙钟排序失效。用存储版本或 HLC。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"先删缓存再写库：读会 miss 打到旧库，填旧，再写库，缓存旧——经典竞态。先写库再删：删丢失则脏。两种都要 TTL。多级缓存每级都要失效或更短 TTL。",-1)),a[6]||(a[6]=e("p",null,[s("与线性一致：只有读穿透到线性一致存储且不读缓存，才保持原档。缓存命中默认掉档，像"),e("a",{href:"/cs/session-guarantees"},"会话"),s("若粘滞同一缓存节点可 RYW，换节点则否。")],-1)),a[7]||(a[7]=e("p",null,"本课不写 CDN 的 PURGE 协议全文。也不写 CPU 缓存 MESI——那是体系结构课。",-1)),(t(),l(o,null,{default:i(()=>[n(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20CASE1%5B%22%E5%85%88%E5%86%99%E5%BA%93%E3%80%81%E5%90%8E%E5%88%A0%E7%BC%93%E5%AD%98%22%5D%0A%20%20%20%20W1%5B%22%E5%86%99%E5%BA%93%20v2%22%5D%20--%3E%20R1%5B%22%E8%AF%BB%20miss%20%E5%A1%AB%20v2%EF%BC%9A%E5%B9%B2%E5%87%80%22%5D%0A%20%20%20%20W1%20--%3E%20L1%5B%22%E5%A4%B1%E6%95%88%E4%B8%A2%E5%A4%B1%20%E2%87%92%20%E8%84%8F%E5%88%B0%20TTL%22%5D%0A%20%20end%0A%20%20subgraph%20CASE2%5B%22%E5%85%88%E5%88%A0%E7%BC%93%E5%AD%98%E3%80%81%E5%90%8E%E5%86%99%E5%BA%93%22%5D%0A%20%20%20%20D2%5B%22%E5%88%A0%E9%94%AE%22%5D%20--%3E%20R2%5B%22%E8%AF%BB%20miss%20%E6%89%93%E5%88%B0%E6%97%A7%E5%BA%93%EF%BC%9A%E5%A1%AB%E5%9B%9E%20v1%22%5D%0A%20%20%20%20R2%20--%3E%20W2%5B%22%E5%86%99%E5%BA%93%20v2%20%E6%99%9A%E5%88%B0%EF%BC%9A%E7%BC%93%E5%AD%98%E9%87%8C%E7%95%99%E7%9D%80%20v1%22%5D%0A%20%20end%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p>这张图回答「两种写序各自的竞态窗口在哪」：先写后删的坏情形是「删丢了」，靠 TTL 兜底；先删后写更阴险——删和写之间任何一次读都会把旧值填回去，且之后无人再删，同样脏到 TTL。数字实例：写库 10 ms、删消息 50 ms 后才到，这 50 ms 里的每个 miss 都可能把 v1 填回并存活一个完整 TTL（如 300 s）。</p><p><span class="marginnote">直觉类比：失效消息像快递柜的「已取件」短信，丢了、晚到了都正常——所以别把正确性押在短信上。TTL 是每周自动对账：不管短信到没到，到期一律重算。版本号则像单号：填充和失效都带上，旧单号晚到也不许覆盖新货。</span></p><p><span class="marginnote">常见误区：初学者常想「用各机器的时钟给失效消息排个序，晚写的删晚点的」。跨机墙钟不可靠：NTP 校准动辄几十毫秒漂移，比写路径还慢，排序结果比乱序更乱。可比顺序只能来自存储里单调递增的版本，或混合逻辑时钟（HLC）这类逻辑时间。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Redis 键空间通知当完备失效。后课默认：缓存是性能层，正确性锚在存储版本与 TTL；失效总线提高新鲜度。下一课处理同时 miss 与热键把存储打穿。</p><p>失效是提示。提示丢失必须有上限脏时间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>失效丢失 ⇒ 脏到 TTL；乱序要用版本。</li><li>先删后写与先写后删都有竞态窗口。</li><li>租约/cas 约束填充，不把缓存升级成 RSM。</li><li>出处：Gray and Cheriton, SOSP 1989；Nishtala et al., NSDI 2013。</li></ul>',8))])}const L=d(B,[["render",T]]);export{C as __pageData,L as default};
